PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_version (version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'learner' CHECK(role IN ('learner','admin')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS topics (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, level TEXT NOT NULL, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vocabulary (id INTEGER PRIMARY KEY AUTOINCREMENT, topic_id INTEGER NOT NULL REFERENCES topics(id), roadmap_topic_id INTEGER REFERENCES roadmap_topics(id) ON DELETE SET NULL, french TEXT NOT NULL, part_of_speech TEXT NOT NULL, gender TEXT, vietnamese TEXT NOT NULL, english TEXT NOT NULL, example_fr TEXT NOT NULL, example_vi TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, vocabulary_id INTEGER NOT NULL REFERENCES vocabulary(id) ON DELETE CASCADE, rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 3), review_count INTEGER NOT NULL DEFAULT 1, last_reviewed_at TEXT NOT NULL, due_at TEXT NOT NULL, PRIMARY KEY(user_id, vocabulary_id));
CREATE TABLE IF NOT EXISTS quizzes (id INTEGER PRIMARY KEY AUTOINCREMENT, topic_id INTEGER NOT NULL REFERENCES topics(id), prompt TEXT NOT NULL, options_json TEXT NOT NULL, answer_key TEXT NOT NULL, explanation TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quiz_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, quiz_id INTEGER NOT NULL REFERENCES quizzes(id), answer TEXT NOT NULL, is_correct INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lesson_progress (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, topic_id INTEGER NOT NULL REFERENCES topics(id) ON DELETE CASCADE, vocabulary_seen INTEGER NOT NULL DEFAULT 0, quiz_correct INTEGER NOT NULL DEFAULT 0, quiz_total INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, PRIMARY KEY(user_id, topic_id));
CREATE TABLE IF NOT EXISTS grammar_activities (id INTEGER PRIMARY KEY AUTOINCREMENT, topic_id INTEGER NOT NULL REFERENCES topics(id) ON DELETE CASCADE, title TEXT NOT NULL, level TEXT NOT NULL, instruction TEXT NOT NULL, prompt TEXT NOT NULL, options_json TEXT NOT NULL, answer_key TEXT NOT NULL, explanation TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS grammar_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, activity_id INTEGER NOT NULL REFERENCES grammar_activities(id) ON DELETE CASCADE, answer TEXT NOT NULL, is_correct INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS roadmap_topics (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL CHECK(kind IN ('grammar','vocabulary')), level TEXT NOT NULL, stage TEXT NOT NULL, day_start INTEGER NOT NULL, day_end INTEGER NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, sort_order INTEGER NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS roadmap_progress (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, topic_id INTEGER NOT NULL REFERENCES roadmap_topics(id) ON DELETE CASCADE, completed INTEGER NOT NULL DEFAULT 0, completed_at TEXT, PRIMARY KEY(user_id, topic_id));
CREATE TABLE IF NOT EXISTS roadmap_lessons (topic_id INTEGER PRIMARY KEY REFERENCES roadmap_topics(id) ON DELETE CASCADE, overview TEXT NOT NULL, objectives_json TEXT NOT NULL, examples_json TEXT NOT NULL, practice_prompt TEXT NOT NULL, answer_hint TEXT NOT NULL, source_note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS roadmap_lesson_details (topic_id INTEGER PRIMARY KEY REFERENCES roadmap_topics(id) ON DELETE CASCADE, detailed_explanation TEXT NOT NULL, notes TEXT NOT NULL, takeaway TEXT NOT NULL, exercises_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vocabulary_details (vocabulary_id INTEGER PRIMARY KEY REFERENCES vocabulary(id) ON DELETE CASCADE, pronunciation TEXT NOT NULL);
INSERT OR IGNORE INTO schema_version(version) VALUES (1);

